<script setup>
import DeploymentAgentEnrollment from '../components/DeploymentAgentEnrollment.vue'
import {agentForHost,hostForAgent} from '../agentHostIdentity.js'
import {formatUnixTime} from '../../shared/datePresentation.js'




import ResourceInventory from '../components/ResourceInventory.vue'
import ResourceAudit from '../components/ResourceAudit.vue'
import {primaryResourceSections,sharedResourceSections,resourceScope} from '../resourceWorkspace.js'
import ResourceGroupsPanel from '../components/ResourceGroupsPanel.vue'
import ResourceCatalogList from '../components/ResourceCatalogList.vue'
import AgentCollectionFields from '../components/AgentCollectionFields.vue'
import {parseVariableLines} from '../resourceCatalog.js'
import ResourceRunnersPanel from '../components/ResourceRunnersPanel.vue'
import {resourceKindLabels,hasConnectionParameters,instanceConnectionConfig} from '../resourceConnections.js'
import PageHeader from "../../shared/components/PageHeader.vue"
import {computed, ref, nextTick, onMounted, onBeforeUnmount, watch} from 'vue'

import UiIcon from '../../shared/components/UiIcon.vue'

import {toast} from '../../shared/composables/toast.js'
import {collectEditor, collectMultiline, selectCollectApplication} from '../agentCollection.js'
import EnvironmentsView from './EnvironmentsView.vue'

const props=defineProps({plugin:{type:String,default:'deploy'},directAPI:Boolean,agentOnly:Boolean,initialSection:String})
const emit=defineEmits(['state'])
const deploymentHost=ref(null),deploymentState=ref({dirty:false,busy:false})
const nestedState=ref({dirty:false,busy:false}),runnerState=ref({dirty:false,busy:false}),runnerVisited=ref(false),pendingWrites=ref(0)
const resourceURL=url=>url.startsWith('api/')?(props.directAPI?url:`/api/resources/${url.slice(4)}`):url
const tab=ref(''),connections=ref([]),hosts=ref([]),groups=ref([]),environments=ref([]),variables=ref([]),audit=ref([]),agentStats=ref([]),applications=ref([])
const showConnection=ref(false),showHost=ref(false),showGroup=ref(false),showVariables=ref(false),showAgent=ref(false),showApplication=ref(false)
const connectionForm=ref({}),hostForm=ref({}),editingHost=ref(null),groupForm=ref({}),variableForm=ref({}),testState=ref({}),hostTestState=ref({})
const applicationForm=ref({name:''})
const hostKeyScanning=ref(false),pendingHostKey=ref(null)
const connectionKeyScanning=ref(false),pendingConnectionHostKey=ref(null)
const agentHost=ref(null),agentForm=ref({}),agentSaving=ref(false),agentApplying=ref(false),agentRemoteState=ref({}),collectionFields=ref(null)
const resourcePending=ref({}),hostPending=ref({}),agentLoading=ref(false),agentPhase=ref('')
const agentBusy=computed(()=>agentSaving.value||agentApplying.value)
const agentIntent=ref('config'),agentLoadError=ref('')
const editorSaves=ref({}),editorForms={},editorBaselines={},connectionEditing=ref(false),variableEditing=ref(false),connectionEditorTab=ref('base'),agentEditorTab=ref('collect')
const connectionHasParameters=computed(()=>hasConnectionParameters(connectionForm.value.kind))
watch(connectionHasParameters,available=>{if(!available)connectionEditorTab.value='base'})
const editorFlags={connection:showConnection,host:showHost,group:showGroup,variables:showVariables,agent:showAgent,application:showApplication}
const editorValues={connection:()=>connectionForm.value,host:()=>hostForm.value,group:()=>groupForm.value,variables:()=>variableForm.value,agent:()=>agentForm.value,application:()=>applicationForm.value}
for(const [key,flag] of Object.entries(editorFlags))watch(flag,visible=>{if(visible)editorBaselines[key]=JSON.stringify(editorValues[key]())},{flush:'sync'})
const editorDirty=key=>editorFlags[key].value&&JSON.stringify(editorValues[key]())!==editorBaselines[key]
const editorBusy=key=>!!editorSaves.value[key]||(key==='connection'&&connectionKeyScanning.value)||(key==='host'&&hostKeyScanning.value)||(key==='agent'&&agentBusy.value)
const resourceNameRules=[{required:true,message:'请填写标识'},{match:/^[a-z][a-z0-9_-]{0,31}$/,message:'小写字母开头，支持小写字母、数字、短横线和下划线，最多 32 位'}]
const friendlyNameRules=[{required:true,message:'请填写名称'},{match:/^[\p{L}\p{N}][\p{L}\p{N}_.-]{0,63}$/u,message:'支持中文、字母、数字、点、短横线和下划线，最多 64 位'}]
const editorRules=computed(()=>({connection:{name:friendlyNameRules,endpoint:connectionForm.value.kind==='aliyun-sae'?[]:[{required:true,message:'请填写服务地址'}]},host:{name:friendlyNameRules,environment:[{required:true,message:'请选择环境'}],addr:[{required:true,message:'请填写主机地址'}]},group:{name:resourceNameRules,environment:[{required:true,message:'请选择环境'}]},variables:{name:resourceNameRules},application:{name:[{required:true,message:'请填写应用名称'}]}}))
async function invalidEditor(key,field,message){editorSaves.value[key]=false;if(key==='connection')connectionEditorTab.value='base';setFieldErrors(editorForms[key],{[field]:{message}},_validationErrors);await nextTick();scrollToValidationField(editorForms[key],field);focusControl(editorForms[key]?.querySelector('[data-resource-field="'+field+'"] input:not([disabled]),[data-resource-field="'+field+'"] textarea'));toast(message,'warning');return false}
async function validateEditor(key){const errors=await _resourceValidators[key]?.();if(!errors)return true;const field=Object.keys(errors)[0];return invalidEditor(key,field,errors[field].message)}
async function canDiscardEditor(key){if(editorBusy(key))return false;return !editorDirty(key)||await confirmAction('关闭将放弃本次未保存的修改，已保存的资源不受影响。','放弃未保存的修改？',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'})}
async function closeEditor(key){if(key==='agent')return closeAgentConfig();if(await canDiscardEditor(key))editorFlags[key].value=false}
function cancelEditor(key){closeEditor(key);return false}
const childState=computed(()=>deploymentState.value.busy?deploymentState.value:tab.value==='runners'?runnerState.value:nestedState.value)
watch(()=>({dirty:Object.keys(editorFlags).some(editorDirty)||childState.value.dirty,busy:Object.keys(resourcePending.value).length>0||Object.values(editorSaves.value).some(Boolean)||pendingWrites.value>0||agentBusy.value||hostKeyScanning.value||connectionKeyScanning.value||Object.keys(hostPending.value).length>0||childState.value.busy}),value=>emit('state',value),{immediate:true})
watch(tab,()=>nestedState.value={dirty:false,busy:false})
let switchingTab=false
async function selectTab(key){
  if(!scope.value.includes(key))return
  if(key===tab.value||switchingTab)return
  if(childState.value.busy||pendingWrites.value||Object.values(editorSaves.value).some(Boolean)||Object.keys(hostPending.value).length||Object.keys(resourcePending.value).length){toast('操作正在进行，请稍候再切换分类','warning');return}
  switchingTab=true
  try{if(childState.value.dirty&&!await confirmAction('切换分类将放弃当前未保存的修改。','放弃未保存的修改？',{confirmButtonText:'放弃并切换',cancelButtonText:'继续编辑'}))return;if((key==='audit'||sharedResourceSections.some(s=>s.key===key))&&primaryResourceSections.some(s=>s.key===tab.value))returnSection.value=tab.value;tab.value=key}
  finally{switchingTab=false}
}
let agentLoadRequest=0,agentAbort=null
function startHostOperation(h,operation){if(hostPending.value[h.name])return false;hostPending.value[h.name]=operation;return true}
function endHostOperation(h){delete hostPending.value[h.name]}
async function closeAgentConfig(){if(!await canDiscardEditor('agent'))return;agentLoadRequest++;agentAbort?.abort();if(agentHost.value&&hostPending.value[agentHost.value.name]==='config-read')endHostOperation(agentHost.value);agentLoading.value=false;showAgent.value=false}
onBeforeUnmount(()=>{agentLoadRequest++;agentAbort?.abort()})
const KINDS=resourceKindLabels
const scope=computed(()=>resourceScope(props.plugin,props.agentOnly))
const primarySections=computed(()=>primaryResourceSections.filter(s=>scope.value.includes(s.key)))
const sharedSections=computed(()=>sharedResourceSections.filter(s=>scope.value.includes(s.key)))
const sharedActive=computed(()=>sharedSections.value.some(s=>s.key===tab.value))
const allowHosts=computed(()=>props.agentOnly||['platform','deploy','logs','monitor'].includes(props.plugin))
const auditScope=ref(null),returnSection=ref('hosts')
async function backToResources(){await selectTab(scope.value.includes(returnSection.value)?returnSection.value:scope.value[0])}
const resourceHeading=computed(()=>tab.value==='audit'?'操作记录':sharedActive.value?'共享配置':'资源中心')
async function openResourceAudit(row){auditScope.value=row?{type:row.category==='hosts'?'host':'connection',id:row.name}:null;await selectTab('audit')}
const PLUGIN_LABELS={platform:'平台全部资源',dbms:'数据库工作台',redis:'Redis 工作台',deploy:'部署平台',logs:'日志查询',monitor:'监控大盘',devtools:'MCP'}
const connectionKinds=computed(()=>Object.entries(KINDS).filter(([kind])=>!['dbms','redis'].includes(props.plugin)||kind===(props.plugin==='dbms'?'mysql':'redis')).map(([value,label])=>({value,label})))

const scopedConnections=computed(()=>connections.value.filter(c=>connectionKinds.value.some(k=>k.value===c.kind)))
const catalogItems=computed(()=>({groups:groups.value,variables:variables.value})[tab.value]||null)
const endpoints={connections:'connections',hosts:'hosts',groups:'host-groups',variables:'variable-groups'}
function createInventory(kind){if(kind==='host')editHost();else editConnection(null,kind)}
function editInventory(row){row.category==='hosts'?editHost(row):editConnection(row)}
function testInventory(row){row.category==='hosts'?testHost(row):testConnection(row)}
async function removeInventory(row){const pending=row.category==='hosts'?hostPending:resourcePending;if(pending.value[row.name])return;pending.value[row.name]='delete';try{await remove('api/'+(row.category==='hosts'?'hosts':'connections')+'/'+encodeURIComponent(row.name),row.name)}finally{delete pending.value[row.name]}}
function createResource(){({connections:editConnection,hosts:editHost,groups:editGroup,variables:editVariables})[tab.value]?.()}
function editResource(row){({connections:editConnection,hosts:editHost,groups:editGroup,variables:editVariables})[tab.value]?.(row)}
async function removeResource(row){if(resourcePending.value[row.name])return;resourcePending.value[row.name]='delete';try{await remove('api/'+endpoints[tab.value]+'/'+encodeURIComponent(row.name),row.name)}finally{delete resourcePending.value[row.name]}}
const pluginLabel=computed(()=>PLUGIN_LABELS[props.plugin]||'当前插件')
const showAgentResources=computed(()=>['logs','platform','deploy','monitor'].includes(props.plugin))
const hostPurpose=computed(()=>props.plugin==='logs'?'管理日志采集主机，并安装或调整采集 Agent':props.plugin==='monitor'?'管理机器监控所依赖的主机身份和 SSH 连接':'主机归属唯一环境，应用发布时通过主机组选择目标')
watch(scope,keys=>{if(!keys.includes(tab.value))tab.value=keys.includes(props.initialSection)?props.initialSection:keys[0]||''},{immediate:true})
async function json(url,opt){const writing=opt?.method&&opt.method!=='GET';if(writing)pendingWrites.value++;try{const r=await fetch(resourceURL(url),opt);const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||'请求失败');return body}finally{if(writing)pendingWrites.value--}}
const asArray=value=>Array.isArray(value)?value:[]
async function loadAgentStats(){const data=await json('/api/plugins/logs/api/stats').catch(()=>({agents:[]}));agentStats.value=asArray(data?.agents)}
const categoryReads={connections:['connections','environments'],resourceGroups:['connections','environments'],hosts:['hosts','environments'],groups:['groups','hosts','environments'],variables:['variables']}
const resourceReads={connections:['api/connections',connections],hosts:['api/hosts',hosts],groups:['api/host-groups',groups],environments:['api/environments',environments],variables:['api/variable-groups',variables],applications:['/api/registry/applications',applications]}
const reading=ref({}),readErrors=ref({}),loaded=new Set(),inflight=new Map()
const currentReading=computed(()=>!!reading.value[tab.value])
const currentReadError=computed(()=>readErrors.value[tab.value]||'')
async function readResource(key,force){
  if(inflight.has(key))return inflight.get(key)
  if(!force&&loaded.has(key))return
  const [url,target]=resourceReads[key]
  const request=Promise.resolve().then(async()=>{try{const result=props.directAPI&&key==='applications'?[]:await json(url);target.value=asArray(result);loaded.add(key)}catch(e){loaded.delete(key);throw e}finally{inflight.delete(key)}})
  inflight.set(key,request);return request
}
async function load(force=true){
  const category=tab.value
  if(category==='runners'){runnerVisited.value=true;return}
  if(!categoryReads[category])return
  const reads=categoryReads[category]
  reading.value[category]=true;readErrors.value[category]=''
  try{await Promise.all(reads.map(key=>readResource(key,force)));if(category==='hosts'&&showAgentResources.value)loadAgentStats()}
  catch(e){readErrors.value[category]=e.message||'请检查网络后重试'}
  finally{reading.value[category]=false}
}
watch(tab,()=>load(false))
onMounted(load)
const post=(url,body)=>json(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
async function remove(url,label){if(!await confirmAction(`删除「${label}」？已被引用的资源可能无法删除。`,'删除资源',{confirmButtonText:'删除'}))return;try{await json(url,{method:'DELETE'});toast('已删除','success');load()}catch(e){toast(e.message,'error')}}
const redisPrefixText=computed({get(){const c=connectionForm.value.config||{};try{if(c.key_prefixes)return JSON.parse(c.key_prefixes).join('\n')}catch{}return c.key_prefix||''},set(value){const prefixes=value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(prefixes.length>1){connectionForm.value.config.key_prefixes=JSON.stringify(prefixes);connectionForm.value.config.key_prefix=''}else{delete connectionForm.value.config.key_prefixes;connectionForm.value.config.key_prefix=prefixes[0]||''}}})
function editConnection(v,kind){
  connectionEditing.value=!!v;connectionEditorTab.value='base'
  const config={tls:'false',db:'0',redis_auth:'password',key_prefix:'',nacos_version:'2.4',nacos_auth:'password',namespace:'',test_data_id:'',test_group:'DEFAULT_GROUP',product_ids:'',bug_status:'closed',baseline:'',sync_minutes:'0',settings_path:'',repository_id:'',mirror_of:'*',region:'cn-hangzhou',oss_bucket:'',oss_endpoint:'',oss_prefix:'logplatform/releases',security_token:'',auth_mode:'https',known_hosts:'',ssh_fingerprint:'',...(v?.config||{})}
  if(v?.kind==='mysql')delete config.database
  connectionForm.value=v?{...v,username:'',password:'',private_key:'',passphrase:'',config}:{name:'',kind:kind||(props.plugin==='dbms'?'mysql':props.plugin==='redis'?'redis':'maven'),endpoint:'',username:'',password:'',private_key:'',passphrase:'',config}
  pendingConnectionHostKey.value=null;connectionKeyScanning.value=false;showConnection.value=true
}
const gitAuthMode=computed({get:()=>connectionForm.value.config?.auth_mode||'https',set:value=>{
  if(!connectionForm.value.config)connectionForm.value.config={}
  if(connectionForm.value.config.auth_mode!==value){connectionForm.value.endpoint='';connectionForm.value.username=value==='ssh'?'git':'';connectionForm.value.password='';connectionForm.value.private_key='';connectionForm.value.passphrase='';connectionForm.value.config.known_hosts='';connectionForm.value.config.ssh_fingerprint='';pendingConnectionHostKey.value=null}
  connectionForm.value.config.auth_mode=value
}})
const xxlAuthMode=computed({
  get:()=>connectionForm.value.config?.xxl_job_auth||(connectionEditing.value?'adapter':'console'),
  set:value=>{
    connectionForm.value.config.xxl_job_auth=value
    connectionForm.value.username=''
    connectionForm.value.password=''
  },
})
function updateConnectionEndpoint(value){
  const previous=(connectionForm.value.endpoint||'').trim();connectionForm.value.endpoint=value
  if(connectionForm.value.kind==='git'&&gitAuthMode.value==='ssh'&&previous&&previous!==value.trim()){connectionForm.value.config.known_hosts='';connectionForm.value.config.ssh_fingerprint='';pendingConnectionHostKey.value=null}
}
async function scanConnectionHostKey(){
  const endpoint=(connectionForm.value.endpoint||'').trim();if(!endpoint)return toast('请先填写 SSH 服务地址','warning')
  connectionKeyScanning.value=true;pendingConnectionHostKey.value=null
  try{const result=await post('api/connections/scan-key',{endpoint});pendingConnectionHostKey.value={...result,requested_endpoint:endpoint}}
  catch(e){toast(e.message,'error')}finally{connectionKeyScanning.value=false}
}
function acceptConnectionHostKey(){
  const result=pendingConnectionHostKey.value
  if(!result||result.requested_endpoint!==(connectionForm.value.endpoint||'').trim()){pendingConnectionHostKey.value=null;return toast('SSH 服务地址已改变，请重新获取指纹','warning')}
  connectionForm.value.config.known_hosts=result.known_hosts;connectionForm.value.config.ssh_fingerprint=result.fingerprint;pendingConnectionHostKey.value=null;toast('Git 服务器指纹已确认','success')
}
async function saveConnection(){
 if(editorSaves.value.connection)return
 editorSaves.value.connection=true
 try{
  if(!await validateEditor('connection'))return
  const f=connectionForm.value
  if(f.kind==='git'&&gitAuthMode.value==='ssh'&&!f.config?.ssh_fingerprint)return invalidEditor('connection','config.ssh_fingerprint','请先获取并确认 Git 服务器 SSH 主机指纹')
  if(f.kind==='git'&&gitAuthMode.value==='ssh'&&!f.secret_configured&&!(f.private_key||'').trim())return invalidEditor('connection','private_key','请填写 SSH 私钥')
  if(f.kind==='xxl_job'&&!f.config.environment)return invalidEditor('connection','config.environment','请选择调度中心所属环境')
  if(f.kind==='xxl_job'){
    const original=connectionEditing.value?connections.value.find(item=>item.name===f.name):null
    const retain=!!original?.secret_configured&&(original.config?.xxl_job_auth||'adapter')===xxlAuthMode.value
    if(xxlAuthMode.value==='console'){
      const sameAddress=retain&&original.endpoint.replace(/\/+$/,'')===f.endpoint.trim().replace(/\/+$/,'')
      if(!sameAddress&&!f.username.trim())return invalidEditor('connection','username','请填写控制台专用账号')
      if((!sameAddress||f.username.trim())&&!f.password.trim())return invalidEditor('connection','password','请填写控制台专用账号的密码')
    }else if((!retain||f.password)&&f.password.trim().length<32){
      return invalidEditor('connection','password','请填写至少 32 字符的 DevOps 接入令牌')
    }
    f.config.xxl_job_auth=xxlAuthMode.value
  }
  await post('api/connections',{...f,config:instanceConnectionConfig(f.kind,f.config)});showConnection.value=false;toast('连接已加密保存','success');await load()
 }catch(e){toast(e.message,'error')}finally{editorSaves.value.connection=false}
}
async function testConnection(v){if(testState.value[v.name]==='testing')return;testState.value[v.name]='testing';try{const r=await post(`api/connections/${v.name}/test`,{});testState.value[v.name]=r.ok?'ok':'fail';const current=connections.value.find(c=>c.name===v.name);if(current&&r.check)current.last_check=r.check;toast(r.ok?'连接测试成功':r.error||r.status||'连接不可达',r.ok?'success':'error')}catch(e){testState.value[v.name]='fail';toast(e.message,'error')}}
function forkConnection(v){editConnection(null,v.kind);connectionForm.value.endpoint=v.endpoint;connectionForm.value.config={...connectionForm.value.config,...v.config};toast('已复制公开连接参数，请填写专用名称与凭据；原连接不会改变','info')}
function editHost(v){editingHost.value=v||null;hostForm.value=v?{...v,password:''}:{name:'',environment:environments.value[0]?.name||'',addr:'',user:'root',key_path:'',password:'',host_key:''};hostKeyScanning.value=false;pendingHostKey.value=null;showHost.value=true}
function updateHostAddress(value){const previous=(hostForm.value.addr||'').trim();hostForm.value.addr=value;pendingHostKey.value=null;if(previous&&previous!==value.trim()&&hostForm.value.host_key)hostForm.value.host_key=''}
async function scanHostKey(){
  const addr=(hostForm.value.addr||'').trim()
  if(!addr)return toast('请先填写主机地址','warning')
  hostKeyScanning.value=true
  pendingHostKey.value=null
  try{const result=await post('api/hosts/scan-key',{addr});pendingHostKey.value={...result,requested_addr:addr}}
  catch(e){toast(e.message,'error')}
  finally{hostKeyScanning.value=false}
}
function acceptHostKey(){
  const result=pendingHostKey.value
  if(!result||result.requested_addr!==(hostForm.value.addr||'').trim()){pendingHostKey.value=null;return toast('主机地址已改变，请重新获取指纹','warning')}
  hostForm.value.host_key=result.fingerprint
  pendingHostKey.value=null
  toast('主机指纹已确认','success')
}
async function saveHost(){
 if(editorSaves.value.host)return
 editorSaves.value.host=true
 try{if(!await validateEditor('host'))return;await post('api/hosts',hostForm.value);showHost.value=false;toast('主机已保存','success');await load()}catch(e){toast(e.message,'error')}finally{editorSaves.value.host=false}
}
async function testHost(v){if(!startHostOperation(v,'ssh-test'))return;hostTestState.value[v.name]='testing';try{const r=await post(`api/hosts/${v.name}/test`,{});hostTestState.value[v.name]=r.ok?'ok':'fail';toast(r.ok?'SSH 连接成功':r.error||'主机不可达',r.ok?'success':'error')}catch(e){hostTestState.value[v.name]='fail';toast(e.message,'error')}finally{endHostOperation(v)}}
function centralAgent(h){return agentForHost(h,agentStats.value,agentRemoteState.value[h.name])}
function agentState(h){const live=centralAgent(h),remote=agentRemoteState.value[h.name];if(live?.online)return {cls:'st-ok',text:'● 在线'};if(remote?.installed&&remote?.active)return {cls:'st-run',text:'◐ 已启动，待上报'};if(remote?.installed)return {cls:'st-fail',text:'○ 服务已停止'};if(remote?.status==='not-installed')return {cls:'dim',text:'未安装'};if(live)return {cls:'dim',text:'○ 离线'};return {cls:'dim',text:'未检测'}}
async function checkAgent(h){if(!startHostOperation(h,'agent-check'))return;try{agentRemoteState.value[h.name]=await json(`api/hosts/${h.name}/agent/status`);toast('Agent 检测完成：'+agentState(h).text,'success')}catch(e){toast(e.message,'error')}finally{endHostOperation(h)}}
async function openAgentConfig(h,mode='config'){
  if(agentBusy.value||!startHostOperation(h,'config-read'))return
  const request=++agentLoadRequest;agentAbort?.abort();agentAbort=new AbortController()
  const host=location.hostname||'127.0.0.1'
  agentEditorTab.value='collect';agentHost.value=h;agentIntent.value=mode;agentLoadError.value='';agentForm.value={};agentLoading.value=true;agentPhase.value='';showAgent.value=true
  try{
    // SSH status is optional: a slow or unreachable host must not hide the configuration editor.
    json(`api/hosts/${h.name}/agent/status`,{signal:agentAbort.signal}).then(status=>{if(request===agentLoadRequest)agentRemoteState.value[h.name]=status}).catch(e=>{if(request===agentLoadRequest)toast('Agent 状态检测失败：'+e.message,'warning')})
    const [cfg]=await Promise.all([json(`api/hosts/${h.name}/agent/config`,{signal:agentAbort.signal}),readResource('applications',false)])
    if(request!==agentLoadRequest)return
    const safeCfg=cfg&&typeof cfg==='object'?cfg:{}
    const savedCollect=asArray(safeCfg.collect).filter(Boolean)
    agentForm.value={...safeCfg,server_url:safeCfg.server_url||`http://${host}:9801`,monitor_url:safeCfg.monitor_url||`http://${host}:9802`,run_user:safeCfg.run_user||'logagent',run_group:safeCfg.run_group||'logagent',spool_max_mb:safeCfg.spool_max_mb||1024,collect:(savedCollect.length?savedCollect:[{application_id:'',service:'',paths:['/var/log/app/*.log'],multiline:''}]).map(collectEditor)}
    editorBaselines.agent=JSON.stringify(agentForm.value);showAgent.value=true
  }catch(e){if(request===agentLoadRequest)agentLoadError.value=e.message}
  finally{if(request===agentLoadRequest){endHostOperation(h);agentLoading.value=false}}
}
function addCollect(){if(!Array.isArray(agentForm.value.collect))agentForm.value.collect=[];agentForm.value.collect.push(collectEditor({application_id:'',service:''}))}
function editApplication(){applicationForm.value={name:''};showApplication.value=true}
async function saveApplication(){
  const name=applicationForm.value.name.trim()
  if(editorSaves.value.application)return
  if(!name)return invalidEditor('application','name','填写应用名称')
  editorSaves.value.application=true
  try{
    const app=await json('/api/registry/applications/observe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,source:'manual'})})
    if(!applications.value.some(item=>item.application_id===app.application_id))applications.value.push(app)
    showApplication.value=false
    if(agentForm.value.collect?.length){const item=agentForm.value.collect.find(c=>!c.application_id)||agentForm.value.collect[agentForm.value.collect.length-1];selectCollectApplication(item,app)}
    toast('平台应用已创建','success')
  }catch(e){toast(e.message,'error')}finally{editorSaves.value.application=false}
}
function removeCollect(i){if(agentBusy.value||agentLoading.value)return;const collect=asArray(agentForm.value.collect);if(!Number.isInteger(i)||i<0||i>=collect.length)return;collect.splice(i,1);agentForm.value.collect=collect}
function agentInstalled(h){return !!(centralAgent(h)||agentRemoteState.value[h.name]?.installed)}
function agentConfigBody(){
  const f=agentForm.value
  if(!f.server_url)return {error:'日志接收地址必填',field:'server_url'}
  if((f.collect||[]).some(c=>c.multiline_mode==='custom'&&!collectMultiline(c)))return {error:'自定义模式需要填写首行正则；无需合并请选择单行日志'}
  const collect=asArray(f.collect).filter(Boolean).map(c=>{const app=asArray(applications.value).find(a=>a.application_id===c.application_id);return {application_id:c.application_id||'',service:app?.name||c.service||'',paths:typeof c.paths_text==='string'?c.paths_text.split('\n').map(x=>x.trim()).filter(Boolean):[],multiline:collectMultiline(c)}})
  if(!collect.length||collect.some(c=>!c.application_id||!c.paths.length))return {error:'每个采集项都要选择平台应用并填写日志路径'}
  return {body:{server_url:f.server_url,monitor_url:f.monitor_url,run_user:f.run_user,run_group:f.run_group,spool_max_mb:f.spool_max_mb,collect}}
}
async function saveAgentConfig(action='save'){
  if(agentLoading.value||agentLoadError.value||agentBusy.value||!agentHost.value)return
  const problem=collectionFields.value?.validate();if(problem){agentEditorTab.value='collect';await nextTick();await collectionFields.value?.focusInvalid(problem);return toast(problem.message,'warning')}
  const prepared=agentConfigBody();if(prepared.error){agentEditorTab.value=prepared.field?'runtime':'collect';await nextTick();if(prepared.field)return invalidEditor('agent',prepared.field,prepared.error);return toast(prepared.error,'warning')}
  const h=agentHost.value
  if(!startHostOperation(h,'config-save'))return
  let configSaved=false
  action==='save'?agentSaving.value=true:agentApplying.value=true
  agentPhase.value='正在保存期望配置…'
  try{
    const saved=await json(`api/hosts/${h.name}/agent/config`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(prepared.body)})
    agentForm.value={...(saved||{}),collect:asArray(saved?.collect).map(collectEditor)}
    configSaved=true;editorBaselines.agent=JSON.stringify(agentForm.value)
    if(action==='apply'){hostPending.value[h.name]='agent-apply';agentPhase.value='正在下发采集配置…';const applied=await post(`api/hosts/${h.name}/agent/config/apply`,{});agentForm.value={...agentForm.value,...applied,collect:asArray(applied?.collect||agentForm.value.collect).map(collectEditor)};agentRemoteState.value[h.name]={installed:true,active:true,status:'active'};toast('采集配置已保存并下发','success')}
    else if(action==='install'){hostPending.value[h.name]='agent-install';agentPhase.value='正在安装 Agent 并应用配置…';const result=await post(`api/hosts/${h.name}/agent/install`,{});agentRemoteState.value[h.name]={installed:true,active:true,status:'active',version:result.version};agentForm.value={...agentForm.value,synchronized:true,applied_at:Math.floor(Date.now()/1000)};toast('Agent 已安装并应用采集配置','success');loadAgentStats()}
    else toast('期望配置已保存，尚未下发','success')
    editorBaselines.agent=JSON.stringify(agentForm.value)
  }catch(e){toast((configSaved&&action!=='save'?'期望配置已保存，但'+(action==='install'?'安装':'下发')+'失败：':'')+e.message,'error')}
  finally{endHostOperation(h);agentSaving.value=false;agentApplying.value=false;agentPhase.value=''}
}

function editGroup(v){groupForm.value=v?{...JSON.parse(JSON.stringify(v)),_existing:true}:{name:'',environment:environments.value[0]?.name||'',description:'',hosts:[],_existing:false};showGroup.value=true}
async function saveGroup(){if(editorSaves.value.group)return;editorSaves.value.group=true;try{if(!await validateEditor('group'))return;await post('api/host-groups',groupForm.value);showGroup.value=false;toast('主机组已保存','success');await load()}catch(e){toast(e.message,'error')}finally{editorSaves.value.group=false}}
function editVariables(v){variableEditing.value=!!v;variableForm.value={name:v?.name||'',description:v?.description||'',raw:'',keys:v?.keys||[]};showVariables.value=true}
async function saveVariables(){
 if(editorSaves.value.variables)return
 editorSaves.value.variables=true
 try{
  if(!await validateEditor('variables'))return
  let values;try{values=parseVariableLines(variableForm.value.raw)}catch(e){return invalidEditor('variables','raw',e.message)}
  await post('api/variable-groups',{name:variableForm.value.name,description:variableForm.value.description,values})
  showVariables.value=false;toast('变量已加密保存','success');await load()
 }catch(e){toast(e.message,'error')}finally{editorSaves.value.variables=false}
}
const fmt=formatUnixTime
const envName=name=>environments.value.find(e=>e.name===name)?.display_name||name
const envProtected=name=>!!environments.value.find(e=>e.name===name)?.protected

