async function openAgentFlow(mode,agentID=''){
 if(mode==='records'){await selectTab('audit');return}
 await selectTab('hosts');await readResource('hosts',false)
 if(!agentID){if(hosts.value.length===1)await openAgentConfig(hosts.value[0],mode);else toast('请选择目标主机，再打开安装／升级或采集配置。','info');return}
 await loadAgentStats()
 const host=hostForAgent(agentID,hosts.value,agentStats.value,agentRemoteState.value)
 if(host)await openAgentConfig(host,mode)
 else toast('此 Agent 尚未关联资源主机，请在采集主机中选择目标。','info')
}
async function closeAgentFlow(){
 if(pendingWrites.value||agentBusy.value)return false
 for(const key of Object.keys(editorFlags))if(editorFlags[key].value){await closeEditor(key);if(editorFlags[key].value)return false}
 return true
}
defineExpose({openAgentFlow,closeAgentFlow})

