<style scoped>.agent-fields{min-width:0;margin:0;padding:0;border:0}.agent-progress{padding:12px;margin-bottom:12px;border:1px solid var(--border);border-radius:var(--radius);background:var(--brand-soft);color:var(--brand-ink)}.agent-progress small{display:block;color:var(--muted-foreground);margin-top:4px}.op-btn:disabled{opacity:.5;cursor:not-allowed}
.agent-actions{position:sticky;bottom:0;z-index:2;flex-wrap:wrap;gap:8px;background:var(--panel);padding:12px 0;border-top:1px solid var(--border)}
.resource-workspace,.resource-content{min-width:0}.resource-tab-label{display:inline-flex;align-items:center;gap:7px}.resource-tabs{margin-bottom:16px}.resource-loading{display:flex;justify-content:center;align-items:center;min-height:240px;width:100%}
.section-head{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}.section-head h3{font-size:1.125rem;margin:0}.section-head p{color:var(--muted-foreground);font-size:.75rem;margin:6px 0 0}.section-head>div:last-child:not(:first-child){margin-left:auto}
.resource-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:16px}.resource-card{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:10px;align-items:start;padding:18px;background:var(--panel);border:1px solid var(--border);border-radius:var(--radius)}.icon{display:grid;place-items:center;width:34px;height:34px;border-radius:var(--radius);background:var(--panel2);font-size:1.125rem}.grow{display:flex;flex-direction:column;min-width:0}.grow>b{font-size:1rem}.grow small{color:var(--muted-foreground);margin:3px 0}.grow code,.grow span{font-size:.75rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.resource-card>b{font-size:.75rem}
.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.modal-actions{display:flex;justify-content:flex-end;margin-top:15px}.pick-list{display:grid;grid-template-columns:1fr 1fr;gap:7px}.pick-list label{display:grid;grid-template-columns:auto 1fr;align-items:center;column-gap:6px;border:1px solid var(--border);padding:8px;border-radius:var(--radius)}.pick-list label.checked{border-color:var(--brand)}.pick-list small{color:var(--muted-foreground);font-size:.75rem}.existing{background:var(--panel2);padding:8px;border-radius:var(--radius);margin-bottom:10px;font-size:.75rem;color:var(--muted-foreground)}
.onboarding{display:flex;min-height:240px;flex-direction:column;align-items:center;justify-content:center;padding:32px;border:1px dashed var(--border);border-radius:var(--radius);color:var(--muted-foreground);text-align:center}.onboarding>span{font-size:2rem}.onboarding h3{margin:8px 0 3px;color:var(--text);font-size:1rem}.onboarding p{max-width:480px;margin-bottom:15px;font-size:.75rem}.dim{color:var(--dim)}
.install-note{padding:9px 11px;margin-bottom:12px;border-radius:var(--radius);background:var(--panel2);color:var(--muted-foreground);font-size:.75rem}.collect-head,.collect-title{display:flex;align-items:center;justify-content:space-between}.collect-head{margin:14px 0 7px}.collect-card{padding:10px 11px;margin-bottom:9px;border:1px solid var(--border);border-radius:var(--radius);background:var(--panel2)}.collect-card .fld:last-child{margin-bottom:0}.install-success{display:flex;flex-direction:column;gap:2px;padding:10px;margin-top:10px;border:1px solid color-mix(in srgb,var(--ok) 45%,var(--border));border-radius:var(--radius);color:var(--ok)}.install-success span,.install-success code{font-size:.75rem;color:var(--muted-foreground)}
.agent-config-state{display:flex;flex-direction:column;gap:2px;padding:10px 11px;margin-bottom:10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--panel2);font-size:.75rem}.agent-config-state span{color:var(--muted-foreground)}.agent-config-state.ok b{color:var(--ok)}.agent-config-state.error b{color:var(--error)}.sync-line{display:flex;align-items:center;justify-content:space-between;margin-bottom:11px;font-size:.75rem}.sync-line small,.collect-head small{display:block;color:var(--muted-foreground);font-weight:400}.collect-head>div{display:flex;flex-direction:column;gap:1px}
.fingerprint-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px}.fingerprint-confirm{margin-top:9px;padding:11px;border:1px solid color-mix(in srgb,var(--brand) 45%,var(--border));border-radius:var(--radius);background:color-mix(in srgb,var(--brand) 6%,var(--panel))}.fingerprint-confirm dl{margin:8px 0;display:grid;gap:5px}.fingerprint-confirm dl>div{display:grid;grid-template-columns:74px minmax(0,1fr);gap:7px}.fingerprint-confirm dt{color:var(--muted-foreground);font-size:.75rem}.fingerprint-confirm dd{margin:0;min-width:0}.fingerprint-confirm code{display:block;overflow-wrap:anywhere;font-size:.75rem}.fingerprint-confirm p{margin:7px 0;color:var(--muted-foreground);font-size:.75rem}.fingerprint-confirm>div:last-child{display:flex;justify-content:flex-end;gap:7px}
.resource-card .grow{min-width:0;flex:none}.resource-card .grow>b,.resource-card .grow>small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.resource-card .actions{grid-column:2/-1;display:flex;align-items:center;gap:4px;min-width:0;padding-top:12px;margin-top:8px;border-top:1px solid var(--border)}
@media(max-width:760px){.resource-grid{grid-template-columns:1fr}.resource-card{padding:14px;grid-template-columns:34px minmax(0,1fr)}.resource-card>b{grid-column:2}.resource-card .actions{grid-column:1/-1}.resource-tabs{margin-bottom:16px}.two{grid-template-columns:1fr}}
.plugin-scope{padding:3px 8px;border-radius:var(--radius);background:color-mix(in srgb,var(--brand) 12%,var(--panel2));color:var(--brand);font-size:.75rem}</style>
